+++ b/audit_main.go
@@ -0,0 +1,99 @@
+package main
+
+import (
+	"context"
+	"encoding/json"
+	"github.com/egoist/mygo"
+	"github.com/egoist/mygo/ui"
+	"os"
+	"path/filepath"
+	"ytmgo/internal/catalog"
+	"ytmgo/internal/language"
+)
+
+// Independent native view fixture. No store, account bridge, player or network.
+func main() {
+	const name = "ytmgo Browser AUDIT"
+	mygo.App.SetName(name)
+	if !mygo.App.RequestSingleInstanceLock() {
+		return
+	}
+	ctx, cancel := context.WithCancel(context.Background())
+	a := &desktop{ctx: ctx, cancel: cancel, queueIndex: -1, historyIndex: -1, accountBusy: true}
+	a.model = UIModel{Route: "home", Appearance: "dark", Language: "zh-Hans", PanelTab: "queue"}
+	a.accountState.message = "nativeAccountWaiting"
+	mygo.App.SetLanguages(language.Supported...)
+	mygo.App.SetLocale("zh-Hans")
+	mygo.Theme.SetSource(mygo.ThemeDark)
+	mode := "account"
+	exe, err := os.Executable()
+	if err != nil {
+		return
+	}
+	evidence := filepath.Clean(filepath.Join(filepath.Dir(exe), "..", "..", "..", "audit-state.json"))
+	last := ""
+	observe := func() {
+		state := struct {
+			Fixture, Mode, Language, AccountMessage                             string
+			RealAccountUsed, AccountBridgeStarted, BrowserFailure, RecoveryOpen bool
+		}{
+			"native_default_browser_ui", mode, a.model.Language, a.accountState.message, false, false, a.model.RecoveryBrowserFailed, a.model.RecoveryOpen}
+		data, err := json.MarshalIndent(state, "", "  ")
+		if err != nil || string(data) == last {
+			return
+		}
+		last = string(data)
+		_ = os.WriteFile(evidence, append(data, '\n'), 0600)
+	}
+	noop := func() {}
+	noItem := func(catalog.Item) {}
+	actions := ViewActions{Tr: a.tr, TrArgs: a.trArgs, Navigate: func(string) {}, Search: func(string) {}, Open: noItem, Play: noItem, QueueAppend: noItem, PlayQueue: func(int) {}, LoadMore: noop, Toggle: noop, Next: noop, Previous: noop, Like: noop, Shuffle: noop, Repeat: noop, Mute: noop, Back: noop, Forward: noop, Reload: noop, Seek: func(float64) {}, Volume: func(float64) {}, Video: func(bool) {}, RetryPlayback: noop, ShowRecovery: a.showRecovery, OpenRecoveryBrowser: a.openRecoveryBrowser}
+	showAccount := func() {
+		mode = "account"
+		a.model.RecoveryOpen = false
+		a.window.SetSize(640, 600)
+		a.window.SetTitle(name + " — ACCOUNT UI ONLY; NO SESSION")
+		a.invalidate()
+	}
+	showRecovery := func() {
+		mode = "recovery"
+		a.model.Error = a.tr("nativeVerificationRequired")
+		a.model.ErrorRecovery = recoveryNotice{Kind: recoveryChallenge, Scope: recoveryCatalog}
+		a.model.Recovery = a.model.ErrorRecovery
+		a.model.RecoveryOpen = true
+		a.model.RecoveryBrowserFailed = false
+		a.window.SetSize(420, 740)
+		a.window.SetTitle(name + " — SYNTHETIC RECOVERY")
+		a.invalidate()
+	}
+	setLanguage := func(tag string) {
+		a.model.Language = tag
+		mygo.App.SetLocale(tag)
+		if mode == "recovery" {
+			a.model.Error = a.tr("nativeVerificationRequired")
+		}
+		a.invalidate()
+	}
+	mygo.App.SetMenu(mygo.NewMenu([]*mygo.MenuItem{{Role: mygo.RoleAppMenu}, {Label: "AUDIT — no accounts", Submenu: []*mygo.MenuItem{
+		menuItem("Account guide 640 × 600", "CmdOrCtrl+1", showAccount),
+		menuItem("Recovery 420 × 740", "CmdOrCtrl+2", showRecovery),
+		menuItem("Recovery 1100 × 840", "CmdOrCtrl+3", func() { showRecovery(); a.window.SetSize(1100, 840) }),
+		mygo.Separator(), menuItem("简体中文", "CmdOrCtrl+4", func() { setLanguage("zh-Hans") }), menuItem("English", "CmdOrCtrl+5", func() { setLanguage("en") }), menuItem("日本語", "CmdOrCtrl+6", func() { setLanguage("ja") }), menuItem("繁體中文", "CmdOrCtrl+7", func() { setLanguage("zh-Hant") }),
+	}}, {Role: mygo.RoleEditMenu}, {Role: mygo.RoleWindowMenu}}))
+	mygo.App.OnBeforeQuit(func(*mygo.QuitEvent) { cancel() })
+	mygo.App.OnWindowAllClosed(func() { mygo.App.Quit() })
+	mygo.App.OnActivate(func(bool) { a.show() })
+	mygo.App.WhenReady(func() {
+		a.window = mygo.NewWindow(mygo.WindowOptions{Title: name, Width: 640, Height: 600, MinWidth: 380, MinHeight: 480, Content: ui.View(func(c *ui.Context) {
+			if mode == "account" {
+				a.accountView(c)
+			} else {
+				nativeView(c, &a.model, actions)
+			}
+			observe()
+		})})
+		a.windowVisible = true
+		showAccount()
+	})
+	_ = mygo.App.Run()
+}
